"""Independent oracle and grading controls, with no simulator required."""
import importlib.util
import math
from pathlib import Path
import tempfile
import unittest

ROOT=Path(__file__).resolve().parents[3]
spec=importlib.util.spec_from_file_location('triangle',ROOT/'benchmark/checkers/triangle_oscillator.py')
m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)


def case():
    return dict(lo=-.5,hi=.5,initial=0.,direction=1,control=[[0,1],[3,1]],stop=3.,maxstep=.25,wave_atol=1e-6,time_atol=2e-7)


def rows():
    # Explicit hand-derived values; not generated by the checker under test.
    z=[0,.25,.5,.25,0,-.25,-.5,-.25,0,.25,.5,.25,0]
    return [dict(time=i/4,z=v,count=int(i>=2)+int(i>=6)+int(i>=10)) for i,v in enumerate(z)]


class TriangleOracle(unittest.TestCase):
    def test_constant(self):
        self.assertEqual(m.roots(case()),[.5,1.5,2.5])
        self.assertTrue(m.evaluate(rows(),case())['passed'])

    def test_nonzero_initial_descending(self):
        c=dict(case(),lo=-.25,hi=.75,initial=.125,direction=-1,control=[[0,.5],[6,.5]],stop=6.)
        self.assertEqual(m.roots(c),[.75,2.75,4.75])
        self.assertAlmostEqual(m.reference(c,0),.125)
        self.assertAlmostEqual(m.reference(c,.75),-.25)
        self.assertAlmostEqual(m.reference(c,2.75),.75)

    def test_ramp_closed_form(self):
        c=dict(case(),control=[[0,1],[3,2.5]])
        # A(t)=t+t^2/4; A(t_k)=1/2+k.
        for k,t in enumerate(m.roots(c)):
            self.assertAlmostEqual(t,2*(math.sqrt(1.5+k)-1))
        self.assertAlmostEqual(m.area(c,3),5.25)

    def test_piecewise_area(self):
        c=dict(case(),control=[[0,1],[1,3],[2,1],[3,1]])
        self.assertEqual(m.area(c,.5),.75)
        self.assertEqual(m.area(c,1),2)
        self.assertEqual(m.area(c,2),4)
        self.assertEqual(m.area(c,3),5)

    def test_bad_waveform_rejected(self):
        r=rows();r[4]['z']+=2e-6
        self.assertFalse(m.evaluate(r,case())['passed'])

    def test_late_explicit_event_rejected(self):
        self.assertFalse(m.evaluate(rows(),case(),[.500001,1.5,2.5])['passed'])

    def test_corrupted_histories_rejected(self):
        mutations=[]
        r=rows();r[0]['count']=1;mutations.append(r)
        r=rows();r[6]['count']=3;mutations.append(r)
        r=rows();r[5]['count']=0;mutations.append(r)
        r=rows();r[4]['z']=float('nan');mutations.append(r)
        r=rows()[:-1];mutations.append(r)
        r=rows();del r[4];mutations.append(r)
        r=rows();r[4]['time']=.1;mutations.append(r)
        for r in mutations:
            with self.subTest(r=r):
                with self.assertRaises(ValueError):m.evaluate(r,case())

    def test_psf_requires_end_and_unique_signals(self):
        with tempfile.TemporaryDirectory() as d:
            p=Path(d)/'x'
            for s in ['VALUE\n"time" 0\n"z" 0\n','VALUE\n"time" 0\n"z" 0\n"z" 1\nEND\n']:
                p.write_text(s)
                with self.assertRaises(ValueError):m.read_psf(p)

    def test_task_checker_is_identical(self):
        self.assertEqual((ROOT/'benchmark/checkers/triangle_oscillator.py').read_bytes(),(ROOT/'benchmark/tasks/va07-triangle-repair/tests/verify.py').read_bytes())

class ExperimentAdapter(unittest.TestCase):
    def test_evas_uses_transient_time_axis(self):
        import oscillator_compatibility as exp
        actual=exp.evas_rows(dict(nodes=['z','count'],solutions=[{'voltages':[0,0]},{'voltages':[.5,1]}],transient={'times':[0,.5]}))
        self.assertEqual(actual,[{'time':0,'z':0,'count':0},{'time':.5,'z':.5,'count':1}])
        with self.assertRaises(ValueError):exp.evas_rows(dict(nodes=[],solutions=[],transient={'times':[0]}))


if __name__=="__main__":unittest.main()
